<!--
 * 系统变量管理页面 — 系统变量的分页列表、搜索、新增、编辑、删除
 *
 * @path apps\system-web\src\views\variable\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 系统变量（列表页）
 * <p>消费后端契约 VariableController（src/api/variable.ts，auto-generated by bash/gen-contract.py）的系统变量列表页：
 * 分页查询 page、编辑/删除（remove）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h, onUnmounted } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page, remove } from '#/api/variable';
import type { PageQuery, VariablePageQuery, VariableVO } from '#/api/models';

import VariableForm from './variable-form.vue';

defineOptions({ name: 'VariableManagement' });

/** 请求控制器，用于取消未完成的请求 */
const abortController = new AbortController();

/** 行类型：真实契约 VariableVO（字段以 models.ts 为准） */
type VariableRow = VariableVO;

/** 分页查询参数：契约 VariablePageQuery + 通用分页字段（models.ts PageQuery） */
type VariablePageQueryParams = VariablePageQuery & PageQuery;

/** 状态是否启用（后端 status 为字符串，兼容 '1' / 'ENABLED' 两种取值） */
function isEnabled(status?: string): boolean {
  return status === '1' || status === 'ENABLED';
}

const gridOptions: VxeTableGridOptions<VariableRow> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'variableKey', title: '变量键', width: 180 },
    { field: 'variableValue', title: '变量值', width: 200 },
    { field: 'valueType', title: '值类型', width: 100 },
    {
      field: 'status',
      title: '状态',
      width: 80,
      slots: {
        default: ({ row }) => {
          const variable = row as VariableRow;
          return h(
            ElTag,
            { type: isEnabled(variable.status) ? 'success' : 'info' },
            () => (isEnabled(variable.status) ? '启用' : '禁用'),
          );
        },
      },
    },
    { field: 'description', title: '描述', width: 200 },
    {
      field: 'action',
      title: '操作',
      width: 140,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const variable = row as VariableRow;
          return h('div', { class: 'flex gap-1' }, [
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(variable) }, () => '编辑'),
            h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(variable) }, () => '删除'),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const query: VariablePageQueryParams = {
          pageNum: pageInfo.currentPage,
          pageSize: pageInfo.pageSize,
          ...formValues,
        };
        const res = await page({ query });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'variableKey', title: '变量键', itemRender: { name: 'Input', props: { placeholder: '变量键' } } },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [VariableFormModal, variableFormApi] = useYDSZModal({ connectedComponent: VariableForm });

function handleAdd() {
  variableFormApi.open();
}

function handleEdit(row: VariableRow) {
  variableFormApi.setData({ record: row });
  variableFormApi.open();
}

async function handleDelete(row: VariableRow) {
  try {
    await ElMessageBox.confirm(`确定删除「${row.variableKey ?? ''}」吗？`, '删除确认', { type: 'warning' });
    if (row.id) await remove({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 页面卸载时取消未完成的请求 */
onUnmounted(() => {
  abortController.abort();
});
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="系统变量">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">新增</ElButton>
      </template>
    </Grid>
    <VariableFormModal @success="gridApi.query()" />
  </Page>
</template>